import Box from '@mui/material/Box'
import Grid from '@mui/material/Grid';
import Stack from '@mui/material/Stack';


function GamesCarousel() {
  return (
    <Box sx={{ flexGrow: 1 }}>
      <Grid container spacing={2}>
        <Grid size={8}>
          
        </Grid>
        <Grid size={4}>
          <Stack spacing={2}>
            
          </Stack>
        </Grid>
        
      </Grid>
    </Box>
    
  );
}

export default GamesCarousel;
